local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["0c069f58aa449494"] = { "Evviva!", "." },
  ["0c079f52ba22a69e"] = { "Allora?", "." },
  ["0c07a6eeba2484bc"] = { "Già.", "." },
  ["0c07a877ba24e45f"] = { "Sì.", "." },
  ["0c07a888ba24e470"] = { "Sì?", "." },
  ["0c07ffbe3de9ab8a"] = { "Come osi chiedermi addestramento, verme? Cosa speravi, <bifolco/bifolca> a bocca aperta, una lezione sull'uso corretto della fogliargento? Fuori! Ringrazia che non ti riempio di botte per avermi fatto perdere tempo.", "." },
  ["0c0a3a853928d74f"] = { "Mi onori con la tua presenza, {race}. Ahimè, per me è troppo tardi. Presto lascerò questo mondo, ma... so così tante cose. Così tanto è racchiuso in questa mia testa. Così tanto che potrebbe aiutare questo mondo a difendersi dalle bestie di questa cittadella della depravazione.\n\nForse, se padroneggi un mestiere... Sì, forse potresti prendere il sapere che custodisco e usarlo per salvare questo mondo.", "." },
  ["0c0c4e7187ea208b"] = { "Va' nella ⟦Valley of Strength=Valle della Forza⟧ e cerca la Banca di Orgrimmar a sud della Sky Tower.", "." },
  ["0c0f61acf899319a"] = { "Il braciere è alto circa un terzo della tua statura e sembra normale, salvo per le iscrizioni lungo le sue lisce sbarre di metallo. Il metallo non mostra alcun segno di usura dovuto alle intemperie, e la coppa in cima è fresca al tatto.", "." },
  ["0c112ded613df865"] = { "Gloria a {name}, <un/una> {class} di valore!", "." },
  ["0c27bb8d420cb24b"] = { "<Goretooth sputa.>\n\nCombatto per l'⟦Horde=Orda⟧, {name}. Mi riempie di rabbia sapere che i nostri nemici se ne stanno in una fortezza, a meno di un giorno di cavallo da Kargath, a tramare contro di noi.\n\nQuanto vorrei liberarmi dai vincoli del dovere e distruggerli tutti in nome del Capoguerra.\n\nAhimè, tutti abbiamo un ruolo da svolgere.", "." },
  ["0c2a1666f178cd1c"] = { "Vattene da qui, {class}, o metteranno in catene anche te.", "." },
  ["0c313ff638c79d75"] = { "Non ho mai avuto molto bisogno di un arco, ma questi fucili che fanno i goblin sono molto comodi per cacciare. Però non riesco ancora ad abituarmi all'odore.", "." },
  ["0c321e715893e731"] = { "Sartoria, dici? Mmm. Ah sì, certo. Dovrai andare a ⟦Thunder Bluff=Picco del Tuono⟧, a nord. Prendi il sentiero che esce dal villaggio per arrivarci. Quando arrivi ai piedi delle alture, prendi l'ascensore fino in cima e parla con uno dei Guardiani del Picco.", "." },
  ["0c3532a7ca37f118"] = { "Dov'è l'istruttore di Conciatura?", "." },
  ["0c3b3ef3f4d57828"] = { "Tutti quei tipi ufficiali stanno a ⟦Ironforge=Forgiardente⟧. Ti conviene passare dal Visitor's Center di ⟦Ironforge=Forgiardente⟧ per i documenti di fondazione di una gilda.", "." },
  ["0c41cc2d0bdecf57"] = { "La Torre di Brinarossa protegge il ⟦Iceblood Garrison=Presidio di Brinarossa⟧ da sud-est.\n\nnon è controllata da nessuna delle due parti.", "." },
  ["0c4e660183bab787"] = { "Tenete duro, fratelli. E non preoccupatevi! La stazza è dalla nostra parte!", "." },
  ["0c53cb91d7bec0c9"] = { "Non dobbiamo far adirare il Padrone. La sua ira è crudele oltre ogni misura.", "." },
  ["0c59d634580ad142"] = { "La mia risposta è Alexstrasza.", "." },
  ["0c6216622225c63d"] = { "Preferiresti affidare i tuoi beni a un goblin?", "." },
  ["0c650fc38f639aeb"] = { "Come risolviamo questa cosa?", "." },
  ["0c6c8673ea627f7e"] = { "Ti stai godendo la festa, {class}?\n\nMentre il custode della fiamma si occupa dei fuochi del presente, io mi dedico più alla storia, e custodisco il ricordo delle feste passate. E naturalmente sto anche documentando i festeggiamenti di quest'anno. Finora va tutto bene, non trovi?\n\nSai, {name}, c'è un potere insito in tutti i fuochi della festa che ardono per tutta la ricorrenza. Noi ci prendiamo cura dei nostri, ma scommetto che ci sono fiamme sacre che ardono nel profondo delle città dei nostri nemici...", "." },
  ["0c74b5986c727a9a"] = { "Impossibile!", "." },
  ["0c74b5a56c727aa7"] = { "Impossibile.", "." },
  ["0c7a7eccfa81dfa7"] = { "Vorrei proseguire l'addestramento nelle vie della Luce.", "." },
  ["0c7abc2e317668b7"] = { "Vi troverò, mortali! Pagherete per aver distrutto gli Ash'ari Crystals!", "." },
  ["0c8afc48b15aacc0"] = { "Nessuno ha mai rubato niente da qui. Mai, in tutta la storia di... tutta la storia!", "." },
  ["0c8d629ca4841eea"] = { "Bel lavoro, soldato. Ora accendiamo i fuochi e sfidiamo la loro ira!", "." },
  ["0c91052311f2c659"] = { "Alcuni di voi non hanno mai combattuto in battaglia. La pace è stata con noi per molti anni. Per molti anni siamo rimasti inattivi, ma per molti anni abbiamo combattuto.", "." },
  ["0c931687e1308980"] = { "La battaglia è vinta! Guardateli fuggire al sicuro nel loro prezioso tempio. Presto tutto sarà raso al suolo... I loro capi distrutti!", "." },
  ["0c9c6e7de6ef5045"] = { "Con la benedizione della Madre Terra, cominciamo.", "." },
  ["0ca1b94f9fbdab1d"] = { "Anche in pace c'è ancora la guerra, e molti clan combattono ancora sotto lo stendardo del Capoguerra. Sei qui per aggiungere il tuo clan a quelli che combattono per Orgrimmar?", "." },
  ["0ca7365030c8d48e"] = { "È il secondo edificio sulla destra nella ⟦Valley of Strength=Valle della Forza⟧, a nord dell'ingresso principale della città. Parla con la locandiera Gryshka.", "." },
  ["0caa4de968168716"] = { "L'⟦Argent Dawn=Alba d'Argento⟧ sarà anche un branco di idealisti impotenti, ma il loro capo, per quanto illuso, sa di essere in inferiorità. La ⟦Scarlet Crusade=Crociata Scarlatta⟧ mi ha mandato qui a rappresentarla. In missione diplomatica, se vuoi... È improbabile che riusciremmo anche solo a scalfire le armate di Kel'Thuzad, unite o no, ma potremmo riuscire a contenerle abbastanza a lungo perché accada una specie di miracolo.\n\nQuanto a me? Morirò in battaglia...\n\n<Marjhan scrolla le spalle.>", "." },
  ["0cb0619747419917"] = { "%s punzecchia il piccolo rospo.", "." },
  ["0cb56176d31f351b"] = { "Aiuto! Guardie! Mi sta per calpestare!", "." },
  ["0cba8167f7cb5c3f"] = { "Sono colui che li sorveglia. Sono il pugno del castigo. Ciò che reprime i ribelli. Osi sfidare il Capoguerra? Osi affrontare il mio giudizio spietato?", "." },
  ["0cc22a5d855551e1"] = { "Il mio sogno è servire un giorno ai tuoi ordini, <padrone/padrona> {name}. Sempre che tu mi giudichi mai all'altezza di simili cose...", "." },
  ["0cc503fe1cbc72dc"] = { "Noma dovrebbe avere la cena pronta a momenti. Tanto vale entrare.", "." },
  ["0cc9a0c74ac8dddb"] = { "Hai portato i libri di testo? Posso guardare sui tuoi?", "." },
  ["0cd755bb93a2a6f2"] = { "È vero che qui si addestrano i paladini?", "." },
  ["0cdb9d7db7f84173"] = { "Perché dici che è una coincidenza, Rabine?", "." },
  ["0ce0cd79712ab35a"] = { "Se posso andare, vorrei controllare come sta Quinn...", "." },
  ["0ce2b4531b5e3d17"] = { "C'è silenzio... Troppo silenzio...", "." },
  ["0ce4a78cb5d05b41"] = { "Zaldimar potrebbe insegnarti qualche nuovo incantesimo. Ultimamente ha preso l'abitudine di stare alla Lion's Pride Inn: potresti controllare una delle stanze e vedere se c'è.", "." },
  ["0ce5be55cf6513ab"] = { "Salute, e <benvenuto/benvenuta>. Sorridere non è il mio forte, ma fidati: sono felice di servirti.", "." },
  ["0cf52af1ece19c39"] = { "%s si mette al lavoro...", "." },
  ["0cf86ac06770419e"] = { "Non farti prendere!", "." },
  ["0cf87b604bb00f19"] = { "Non posso aiutarti. Di pozioni ne sai più tu di me. E poi ho delle pentole da sorvegliare. Parla con Yelmak, laggiù. Di pozioni se ne intende parecchio.", "." },
})
